<script setup lang="ts">import { router, usePage } from '@inertiajs/vue3';import { ref } from 'vue';import { CheckCircle2, Upload } from 'lucide-vue-next';import BusinessLayout from '@/layouts/BusinessLayout.vue';defineProps<{batches:any}>();const file=ref<File|null>(null);const page=usePage<any>();const upload=()=>file.value&&router.post('/admin/authorization-import/preview',{file:file.value},{forceFormData:true});const commit=(id:string)=>router.post(`/admin/authorization-import/${id}/commit`);</script><template><BusinessLayout title="授权名单" eyebrow="岗位权限管理"><div class="mb-5 grid gap-5 border border-[#ded7c9] bg-white p-5 lg:grid-cols-[1fr_auto]"><div><h2 class="font-serif text-lg font-semibold">导入学院提交人</h2><p class="mt-1 text-sm text-[#75807b]">列：工号/统一账号、姓名、学院代码、岗位角色、启用状态。支持 CSV/XLSX。</p><input class="mt-4 block text-sm" type="file" accept=".csv,.xlsx" @change="file=($event.target as HTMLInputElement).files?.[0]||null"></div><button class="btn-primary self-end" @click="upload"><Upload :size="16"/>上传并校验</button></div><div class="table-card"><table><thead><tr><th>批次</th><th>状态</th><th>记录数</th><th>错误数</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="b in batches.data" :key="b.id"><td class="font-mono text-xs">{{b.id}}</td><td>{{b.status}}</td><td>{{b.payload.length}}</td><td>{{b.errors?.length||0}}</td><td>{{b.created_at?.slice(0,16)}}</td><td><button v-if="b.status==='preview'&&!b.errors?.length" class="inline-flex items-center gap-1 text-[#2f6a59]" @click="commit(b.id)"><CheckCircle2 :size="15"/>确认生效</button><span v-else class="text-xs text-slate-400">—</span></td></tr></tbody></table></div></BusinessLayout></template>
